import json
import random
import base64
import sys

if hasattr(sys.stdout, 'reconfigure'):
    sys.stdout.reconfigure(encoding='utf-8')

random.seed(42)

dataset = []
seen_prompts = set()
idx_att = 1
idx_ben = 1

def add_entry(prompt, is_attack, category, subtype, hard_neg=False, expected="Block"):
    global idx_att, idx_ben
    cleaned = prompt.strip()
    if not cleaned or cleaned in seen_prompts:
        return False
    seen_prompts.add(cleaned)
    
    if is_attack:
        entry_id = f"VLPID-ATT-{idx_att:04d}"
        idx_att += 1
    else:
        entry_id = f"VLPID-BEN-{idx_ben:04d}"
        idx_ben += 1
        
    dataset.append({
        "id": entry_id,
        "prompt": cleaned,
        "is_attack": is_attack,
        "category": category,
        "subtype": subtype,
        "language": "vi",
        "hard_negative": hard_neg,
        "expected_action": expected
    })
    return True

