dataset = dataset[:1000]

output_file = "v_lpid_1k.jsonl"
with open(output_file, "w", encoding="utf-8") as f:
    for item in dataset:
        f.write(json.dumps(item, ensure_ascii=False) + "\n")

attack_count = sum(1 for x in dataset if x["is_attack"])
benign_count = sum(1 for x in dataset if not x["is_attack"] and not x["hard_negative"])
hard_neg_count = sum(1 for x in dataset if x["hard_negative"])

category_stats = {}
subtype_stats = {}
for item in dataset:
    cat = item["category"]
    sub = item["subtype"]
    category_stats[cat] = category_stats.get(cat, 0) + 1
    subtype_stats[sub] = subtype_stats.get(sub, 0) + 1

